import{_ as r,C as o,o as s,c as n,j as t,a as h,E as i,ak as p}from"./chunks/framework.sV-XtlWr.js";const f=JSON.parse(`{"title":"Replay a bug report","description":"Play a bug report's steps again in a tab with Piwi Picker, with a cursor and a caption per step, and see whether the bug shows on your own dev server, or run them with Playwright in the desktop app.","frontmatter":{"title":"Replay a bug report","description":"Play a bug report's steps again in a tab with Piwi Picker, with a cursor and a caption per step, and see whether the bug shows on your own dev server, or run them with Playwright in the desktop app.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/replay-a-bug-report.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/replay-a-bug-report.html"}],["meta",{"property":"og:title","content":"Replay a bug report | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Play a bug report's steps again in a tab with Piwi Picker, with a cursor and a caption per step, and see whether the bug shows on your own dev server, or run them with Playwright in the desktop app."}]]},"headers":[],"relativePath":"features/replay-a-bug-report.md","filePath":"features/replay-a-bug-report.md","lastUpdated":1791294253000}`),l={name:"features/replay-a-bug-report.md"};function d(u,e,c,g,w,y){const a=o("Needs");return s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"replay-a-bug-report",tabindex:"-1"},[h("Replay a bug report "),t("a",{class:"header-anchor",href:"#replay-a-bug-report","aria-label":'Permalink to "Replay a bug report"'},"​")],-1)),i(a,{extension:""}),e[1]||(e[1]=p('<p><strong>Replay</strong> plays a <a href="./report-a-bug.html">bug report</a>&#39;s steps again in a tab, with a cursor that moves to each element and a caption saying what it does, then says whether the bug shows there. It suits the developer who receives the report: open the app on your own dev server, and the steps run there, with your session and your browser&#39;s developer tools at hand.</p><h2 id="choosing-a-report" tabindex="-1">Choosing a report <a class="header-anchor" href="#choosing-a-report" aria-label="Permalink to &quot;Choosing a report&quot;">​</a></h2><ul><li>From the finished report, <strong>Replay</strong> plays it at once on the same site.</li><li>From the popup, <strong>Replay a bug report</strong> (<code>R</code>) asks for the site&#39;s access if needed, then for the report: the <a href="/reference/bug-report-file.html"><code>.piwibug</code> file</a> (or the same file named <code>.zip</code>) or its <code>steps.json</code>, the report just recorded in this browser, or, connected, one of the project&#39;s reports on Piwi.</li></ul><p>The steps run on the tab&#39;s site, whichever site they were recorded on.</p><h2 id="the-answer" tabindex="-1">The answer <a class="header-anchor" href="#the-answer" aria-label="Permalink to &quot;The answer&quot;">​</a></h2><p>Each element is found with the locator the failing test uses, and waited for as Playwright waits: exactly one match, visible, enabled and still. The replay ends with one of three answers:</p><ul><li><strong>Reproduced</strong>: an expected result does not hold, such as a total that still reads &quot;Total: 50&quot;, and the panel says whether that is the value reported.</li><li><strong>Not reproduced</strong>: every expected result holds here.</li><li><strong>Could not reach the bug</strong>: a step could not be played (it found no element, several, or a disabled one, or the flow ended on another page) and you stopped there. The data, the login or a flag differ here.</li></ul><p>Under the answer, the panel lists the failed requests and console errors the page showed during the replay, such as &quot;POST /api/cart/coupon answered 500&quot;. For a report from Piwi, <strong>Share result…</strong> records the answer on the report, with the site it ran on, after showing what it sends.</p><p><strong>Step by step</strong> waits for <strong>Next</strong> before each step, with the element outlined, so you can set a breakpoint first.</p><h2 id="when-a-step-cannot-be-played" tabindex="-1">When a step cannot be played <a class="header-anchor" href="#when-a-step-cannot-be-played" aria-label="Permalink to &quot;When a step cannot be played&quot;">​</a></h2><p>A step Replay cannot play is handed to you rather than ending the replay. The panel says why, names the step in words and, when the report has <a href="./report-a-bug.html#evidence">a screenshot of each step</a>, shows the page as it began there, the element outlined. It lists the locators the element was recorded with and outlines on the page every element they still find, such as two buttons where the recording saw one, as the page changes. Do it yourself on the page, then choose:</p><ul><li><strong>I did it, continue</strong>: the replay goes on with the next step, even when your action loaded another page.</li><li><strong>Skip this step</strong>: it goes on without it.</li><li><strong>Stop here</strong>: it ends there, and says it could not reach the bug.</li></ul><p>Under the answer, the panel lists the steps played by hand.</p><h2 id="trusted-input" tabindex="-1">Trusted input <a class="header-anchor" href="#trusted-input" aria-label="Permalink to &quot;Trusted input&quot;">​</a></h2><p>In Chrome and Edge, Replay sends trusted input as Playwright does: a real hover, clicks, keys and drags that the page cannot tell from a person&#39;s. Chrome shows its debugging bar until the replay ends. In Firefox, when the browser refuses the session, once the bar is cancelled, or once the browser refuses one of its commands (the bar then closes), Replay goes on with the page&#39;s own events; the panel says which, step by step.</p><p>A report names the files a step chose but never carries them: Replay asks you to choose them, or to skip the step.</p><p>With trusted input, each step plays at the viewport size it was recorded at, in CSS pixels whatever your zoom, and the tab gets its own size back when the replay ends. Otherwise the panel says when the window&#39;s size differs from the recorded one, so you can resize it.</p><h2 id="running-it-with-playwright" tabindex="-1">Running it with Playwright <a class="header-anchor" href="#running-it-with-playwright" aria-label="Permalink to &quot;Running it with Playwright&quot;">​</a></h2><p><strong>Run with Playwright…</strong>, beside <strong>Start</strong> and on a finished replay, sends the steps to the paired <a href="./bug-reports.html#running-it-with-playwright-in-the-desktop-app">desktop app</a>, which runs them in your project once you confirm it there.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>It plays one site, in the top-level document only, as the report was recorded. A step that opens another site, or an address that is not a web page, is handed to you.</li><li><strong>Share result…</strong> and <strong>Run with Playwright…</strong> are the only parts that send anything, each after showing what it sends.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./report-a-bug.html">Report a bug</a>: recording the report Replay plays</li><li><a href="./bug-reports.html">Bug reports</a>: the reports kept on your instance</li><li><a href="/reference/bug-report-file.html">Bug report file format</a>: what a <code>.piwibug</code> holds</li></ul>',23))])}const m=r(l,[["render",d]]);export{f as __pageData,m as default};
